describe('Faceted Search Functionality', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to your application's search page
    });

    it('should update results when a facet is selected', () => {
        cy.get('.facet-category').first().click(); // Click on the first facet category
        cy.get('.search-results').should('exist'); // Ensure search results are displayed
        cy.get('.search-results').children().should('have.length.greaterThan', 0); // Check that results are returned
    });

    it('should not display results when no facets are selected', () => {
        cy.get('.search-results').should('exist'); // Ensure search results area is present
        cy.get('.search-results').children().should('have.length', 0); // Check that no results are returned
    });
});
